// Input: the webhook body sent by the review app.
const b = $input.first().json.body;
const r = b.request;
const requestText = [
  `Project name: ${r.project_name}`,
  `Business department: ${r.department}`,
  `Priority: ${r.priority}`,
  `Requested completion date: ${r.requested_date || '(not supplied)'}`,
  `Stakeholders: ${r.stakeholders || '(not supplied)'}`,
  `Business objective: ${r.business_objective || '(not supplied)'}`,
  `Request description: ${r.description}`,
].join('\n');

const item = {
  type: 'object',
  properties: {
    text: { type: 'string' },
    source: { type: 'string', enum: ['stated', 'suggested'] },
    evidence: { type: 'string' },
  },
  required: ['text', 'source', 'evidence'],
};
const task = {
  type: 'object',
  properties: {
    ...item.properties,
    suggested_owner: { type: ['string', 'null'] },
    due_date: { type: ['string', 'null'] },
  },
  required: ['text', 'source', 'evidence', 'suggested_owner', 'due_date'],
};
const list = (of) => ({ type: 'array', items: of, maxItems: 6 });
const schema = {
  type: 'object',
  properties: {
    objective: item,
    requirements: list(item),
    tasks: list(task),
    dependencies: list(item),
    risks: list(item),
    missing_information: list(item),
  },
  required: ['objective', 'requirements', 'tasks', 'dependencies', 'risks', 'missing_information'],
};

const system = `You are a project coordination assistant. You read ONE project request and return JSON only.
Today's date is ${b.today}.

Rules:
1. Every item has a "source". Use "stated" ONLY when the request explicitly says it. Then "evidence" must be a short exact quote copied word for word from the request (at most 20 words).
2. Use "suggested" when you infer or propose something yourself. Then "evidence" must be an empty string.
3. Never invent names, dates, budgets or numbers.
4. tasks: concrete actions needed to deliver the request. When the request says a named person or team will do something, that is a "stated" task: quote it and put that person or team in "suggested_owner". "suggested_owner" may only be a person, role or department that appears in the request, otherwise null. "due_date" only when the request gives a date for that task, written YYYY-MM-DD, otherwise null.
5. dependencies: things this project relies on (other teams, systems, approvals, data).
6. risks: realistic risks for this specific request.
7. missing_information: information a project manager needs that the request does NOT provide (for example project owner, budget, scope boundaries, success criteria, deadline, stakeholders, approvals). List only what is really absent. If a field says "(not supplied)", it is missing.
8. At most 6 items per list. One sentence per item. Return empty lists when there is nothing to report.`;

return [{
  json: {
    ctx: b,
    requestText,
    ollamaBody: {
      model: b.model,
      stream: false,
      format: schema,
      options: { temperature: 0, num_ctx: 8192, num_predict: 1400 },
      messages: [
        { role: 'system', content: system },
        { role: 'user', content: requestText },
      ],
    },
  },
}];

// Parse the extraction and prepare the summary call.
const first = $('Build extraction request').first().json;
const extraction = JSON.parse($input.first().json.message.content);

const strings = { type: 'array', items: { type: 'string' }, maxItems: 6 };
const schema = {
  type: 'object',
  properties: {
    executive_summary: { type: 'string' },
    objectives: strings,
    key_milestones: strings,
    outstanding_actions: strings,
    potential_blockers: strings,
    stakeholder_responsibilities: strings,
  },
  required: ['executive_summary', 'objectives', 'key_milestones', 'outstanding_actions', 'potential_blockers', 'stakeholder_responsibilities'],
};

const system = `You write a structured project summary for a project manager. Return JSON only.
Today's date is ${first.ctx.today}.

Rules:
1. Use only the project request and the extracted items you are given.
2. Anything that is not stated in the request must start with "(Suggested)".
3. Never invent names, dates, budgets or numbers. If no date is given, do not create one.
4. executive_summary: 2 to 3 sentences.
5. key_milestones: only milestones that follow from the request. Include a date only when the request gives it. If a requested completion date is supplied, include it as the final milestone.
6. stakeholder_responsibilities: only for stakeholders named in the request. If none are named, return one item saying that stakeholders are not yet identified.
7. At most 6 items per list. One sentence per item.`;

const user = `PROJECT REQUEST\n${first.requestText}\n\nEXTRACTED ITEMS (JSON)\n${JSON.stringify(extraction)}`;

return [{
  json: {
    extraction,
    ollamaBody: {
      model: first.ctx.model,
      stream: false,
      format: schema,
      options: { temperature: 0, num_ctx: 8192, num_predict: 900 },
      messages: [
        { role: 'system', content: system },
        { role: 'user', content: user },
      ],
    },
  },
}];

// Parse the summary and prepare the stakeholder update call.
const first = $('Build extraction request').first().json;
const extraction = $('Build summary request').first().json.extraction;
const summary = JSON.parse($input.first().json.message.content);

const strings = { type: 'array', items: { type: 'string' }, maxItems: 6 };
const schema = {
  type: 'object',
  properties: {
    subject: { type: 'string' },
    progress: { type: 'string' },
    completed_activities: strings,
    outstanding_tasks: strings,
    upcoming_milestones: strings,
    risks_and_decisions: strings,
  },
  required: ['subject', 'progress', 'completed_activities', 'outstanding_tasks', 'upcoming_milestones', 'risks_and_decisions'],
};

const system = `You draft a status update for the stakeholders of a project. A human will review and edit it before anything is sent. Return JSON only.
Today's date is ${first.ctx.today}.

Rules:
1. The project has only just been requested. Work has not started unless the request says otherwise.
2. Use only facts from the request and the extracted items. Never invent progress, names, dates or numbers.
3. completed_activities: only activities the request says are already done. Otherwise return an empty list.
4. progress: 1 to 2 sentences on where the project stands today.
5. risks_and_decisions: the main risks, and the decisions or missing information the stakeholders must provide.
6. Plain, professional tone. At most 6 items per list. One sentence per item.`;

const user = `PROJECT REQUEST\n${first.requestText}\n\nEXTRACTED ITEMS (JSON)\n${JSON.stringify(extraction)}`;

return [{
  json: {
    summary,
    ollamaBody: {
      model: first.ctx.model,
      stream: false,
      format: schema,
      options: { temperature: 0, num_ctx: 8192, num_predict: 900 },
      messages: [
        { role: 'system', content: system },
        { role: 'user', content: user },
      ],
    },
  },
}];

// Collect all three AI outputs into one result for the review app.
const ctx = $('Build extraction request').first().json.ctx;
const extraction = $('Build summary request').first().json.extraction;
const summary = $('Build update request').first().json.summary;
const update = JSON.parse($input.first().json.message.content);
return [{ json: { request_id: ctx.request_id, result: { extraction, summary, update } } }];
